BEGIN;
CREATE EXTENSION IF NOT EXISTS postgis;
DROP TABLE IF EXISTS enlaces_topo CASCADE;
DROP TABLE IF EXISTS enlaces_topo_vertices_pgr CASCADE;
DROP TABLE IF EXISTS nodos_clave CASCADE;
DROP TABLE IF EXISTS factor_capa CASCADE;
DROP TABLE IF EXISTS parametros_modelo CASCADE;
DROP TABLE IF EXISTS sismo CASCADE;

CREATE TABLE sismo (id_evento text PRIMARY KEY, titulo text, magnitud double precision, tipo_magnitud text, fecha_utc timestamptz, profundidad_km double precision, consulta_usgs text, geom geometry(Point, 4326));

CREATE TABLE parametros_modelo (parametro text PRIMARY KEY, valor double precision, unidad text, fuente text);

CREATE TABLE factor_capa (capa text PRIMARY KEY, montaje text, k double precision, k_fragil double precision, criterio text);

CREATE TABLE nodos_clave (id integer PRIMARY KEY, nombre text, region text, genera boolean, intercambia boolean, recibe boolean, infraestructura text, incluir boolean, vertice_id bigint, vertice_red bigint, dist_vertice_km double precision, geom geometry(Point, 4326));

CREATE TABLE enlaces_topo_vertices_pgr (id bigint PRIMARY KEY, the_geom geometry(Point, 4326));

CREATE TABLE enlaces_topo (id integer PRIMARY KEY, source integer, target integer, capa text, sintetico boolean, longitud_km double precision, dist_epicentro_km double precision, mmi_max double precision, pgv_max_cms double precision, cortes_esperados double precision, p_falla double precision CHECK (p_falla BETWEEN 0 AND 1), p_falla_menos_sigma double precision, p_falla_mas_sigma double precision, p_falla_aereo_fragil double precision, p_falla_shakemap double precision, geom geometry(LineString, 4326));

CREATE INDEX enlaces_topo_geom_idx ON enlaces_topo USING gist (geom);
CREATE INDEX enlaces_topo_source_idx ON enlaces_topo (source);
CREATE INDEX enlaces_topo_target_idx ON enlaces_topo (target);
COMMIT;

SELECT capa, sintetico, count(*) AS enlaces, round(sum(longitud_km)::numeric, 1) AS km,
       round(max(p_falla)::numeric, 4) AS p_max, round(avg(p_falla)::numeric, 4) AS p_media
FROM enlaces_topo GROUP BY capa, sintetico ORDER BY sintetico, capa;
